<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';import{queryEntity}from'../api/admin.js';const items=ref([]),current=ref(),drawer=ref(false);onMounted(async()=>items.value=(await queryEntity('service')).data.items);function open(x){current.value=x;drawer.value=true}function done(){current.value.status='已处理';drawer.value=false;ElMessage.success('会话已标记为已处理')}</script><template><div class="admin-page"><PageHeader title="智能客服" description="查看客户常见问题与静态客服处理记录"/><div class="work-surface"><div class="filter-bar"><el-input placeholder="客户 / 问题关键词" style="width:240px"/><el-select placeholder="处理状态" style="width:140px"><el-option label="待处理" value="待处理"/><el-option label="已处理" value="已处理"/></el-select><el-button type="primary" plain>查询</el-button></div><div class="table-wrap"><el-table :data="items"><el-table-column prop="id" label="会话编号" width="130"/><el-table-column prop="customer" label="客户" width="100"/><el-table-column prop="category" label="问题分类" width="120"/><el-table-column prop="lastMessage" label="最近消息" min-width="280"/><el-table-column prop="time" label="时间" width="160"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看</el-button></template></el-table-column></el-table></div></div><el-drawer v-model="drawer" title="客服会话" size="600px"><div v-if="current"><p class="conversation-meta">{{current.customer}} · {{current.category}} · {{current.time}}</p><div class="bubble user">{{current.lastMessage}}</div><div class="bubble">您好，相关问题已记录。客服人员会结合订单和材料信息为您进一步确认。</div><el-button type="primary" style="margin-top:24px" @click="done">标记已处理</el-button></div></el-drawer></div></template><style scoped>.conversation-meta{color:var(--muted);border-bottom:1px solid var(--border);padding-bottom:14px}.bubble{max-width:80%;padding:12px 14px;background:var(--bg);margin:16px 0}.bubble.user{margin-left:auto;background:#eee3da}</style>
